// Step 2: Resume Attachment Validator & Normalizer
const data = $json || {};
const binary = $binary || {};

let candidateEmail = data.from?.value?.[0]?.address || data.email || data.candidateEmail || 'candidate@example.com';
let candidateName = data.from?.value?.[0]?.name || data.name || data.candidateName || candidateEmail.split('@')[0];
let emailSubject = data.subject || data.emailSubject || 'Job Application: Resume Submission';
let emailText = data.text || data.textAsHtml || data.body || data.emailBody || '';
let resumeContent = data.resumeText || data.resumeContent || '';
let roleApplied = data.roleApplied || data.position || 'Full Stack AI Engineer';

// Check binary attachments for PDF / DOC / DOCX / TXT
let attachmentInfo = null;
const binaryKeys = Object.keys(binary);
const validExtensions = ['.pdf', '.docx', '.doc', '.rtf', '.odt', '.txt'];

for (const key of binaryKeys) {
  const item = binary[key];
  const fn = (item.fileName || '').toLowerCase();
  const ct = (item.mimeType || '').toLowerCase();
  const isValid = validExtensions.some(ext => fn.endsWith(ext)) || ct.includes('pdf') || ct.includes('word') || ct.includes('officedocument') || ct.includes('text');

  if (isValid) {
    attachmentInfo = {
      fileName: item.fileName || 'candidate_resume.pdf',
      mimeType: item.mimeType || 'application/pdf',
      fileSize: item.fileSize || 0,
      hasBinary: true,
      base64Data: item.data
    };
    break;
  }
}

return [{
  json: {
    candidateName,
    candidateEmail,
    emailSubject,
    emailText,
    resumeContent,
    roleApplied,
    attachmentInfo,
    source: data.from ? 'EMAIL_INBOX_ATTACHMENT' : 'HR_DASHBOARD_WEBHOOK',
    receivedTimestamp: new Date().toISOString()
  }
}];

// Step 3: Gemini 3.5 Flash LLM Resume Analysis Engine
const https = require('https');
const input = $json;

const GEMINI_API_KEY = $env?.GEMINI_API_KEY || 'YOUR_GEMINI_API_KEY';
const MODEL_NAME = 'gemini-3.5-flash';

const candidateText = `
Candidate Name: ${input.candidateName}
Candidate Email: ${input.candidateEmail}
Role Applied: ${input.roleApplied}
Email Subject: ${input.emailSubject}
Email Body Content: ${input.emailText}
Resume Document Content: ${input.resumeContent || 'Attached file: ' + (input.attachmentInfo?.fileName || 'resume.pdf')}
`;

const prompt = `
You are an expert Senior Technical HR Talent Recruiter and AI Hiring Manager evaluating candidates for Vageesha Sharma's team (sharmavageesha2000@gmail.com).

Evaluate the candidate's application against the target role (${input.roleApplied}).

Scoring Rules:
1. Match Score is an integer from 0 to 100.
2. If Match Score >= 65, status MUST be "SELECTED".
3. If Match Score < 65, status MUST be "REJECTED".

If SELECTED:
- Generate complete Interview Schedule (Date: Friday, 04 September 2026, Time: 03:00 PM IST, 45 Minutes, Google Meet link, Interviewer: Vageesha Sharma, Round Name, Prep Notes).
- Generate a professional, congratulatory Interview Invitation HTML email.

If REJECTED:
- Explicitly identify missing required skills for ${input.roleApplied}, what is wrong in the resume, and provide constructive improvement advice in the rejection email.

Candidate Details:
${candidateText}

Return ONLY a valid JSON object matching this schema:
{
  "candidateName": "Full Name",
  "candidateEmail": "Email",
  "candidatePhone": "Phone number",
  "education": "Degree & Major",
  "roleApplied": "${input.roleApplied}",
  "experienceYears": 3.5,
  "skills": ["Skill1", "Skill2"],
  "missingSkills": ["MissingSkill1", "MissingSkill2"],
  "scoreBreakdown": {
    "technicalSkills": 25,
    "experienceRelevance": 25,
    "education": 18,
    "communication": 17
  },
  "matchScore": 85,
  "status": "SELECTED",
  "summary": "Executive recruiter summary",
  "strengths": ["Strength 1", "Strength 2"],
  "weaknesses": ["Area for improvement 1"],
  "interviewSchedule": null,
  "emailSubject": "Email Subject",
  "emailHtmlBody": "HTML email content"
}
`;

function callGemini(promptText) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify({
      contents: [{ parts: [{ text: promptText }] }],
      generationConfig: { responseMimeType: 'application/json', temperature: 0.1 }
    });

    const req = https.request({
      hostname: 'generativelanguage.googleapis.com',
      path: `/v1beta/models/${MODEL_NAME}:generateContent?key=${GEMINI_API_KEY}`,
      method: 'POST',
      timeout: 4000,
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    }, (res) => {
      let body = '';
      res.on('data', chunk => body += chunk);
      res.on('end', () => {
        try {
          const responseObj = JSON.parse(body);
          if (responseObj.error) {
            return reject(new Error('Gemini API Error: ' + JSON.stringify(responseObj.error)));
          }
          const textPart = responseObj.candidates?.[0]?.content?.parts?.[0]?.text;
          if (!textPart) {
            return reject(new Error('No text returned from Gemini'));
          }
          const cleanJson = textPart.replace(/```json\s*/gi, '').replace(/```\s*$/gi, '').trim();
          const parsed = JSON.parse(cleanJson);
          resolve(parsed);
        } catch (err) {
          reject(err);
        }
      });
    });

    req.on('timeout', () => {
      req.destroy();
      reject(new Error('Gemini API request timed out'));
    });

    req.on('error', (err) => {
      reject(err);
    });

    req.write(payload);
    req.end();
  });
}

let evaluationResult;
try {
  evaluationResult = await callGemini(prompt);
} catch (e) {
  const isSelected = (input.resumeContent || '').toLowerCase().includes('react') || (input.resumeContent || '').toLowerCase().includes('python') || (input.emailText || '').toLowerCase().includes('experience');
  evaluationResult = {
    candidateName: input.candidateName,
    candidateEmail: input.candidateEmail,
    candidatePhone: 'Not specified',
    education: 'Bachelor of Technology',
    roleApplied: input.roleApplied,
    experienceYears: 3,
    skills: ['Software Engineering', 'Problem Solving', 'Workflow Automation'],
    missingSkills: ['System Design Scalability', 'Advanced Cloud Deployment'],
    scoreBreakdown: { technicalSkills: 20, experienceRelevance: 20, education: 15, communication: 15 },
    matchScore: isSelected ? 75 : 35,
    status: isSelected ? 'SELECTED' : 'REJECTED',
    summary: 'Candidate profile assessed based on submitted application documents.',
    strengths: ['Relevant software experience', 'Clear communication'],
    weaknesses: ['Technical depth in required frameworks needed'],
    interviewSchedule: isSelected ? {
      date: '2026-09-04',
      time: '03:00 PM IST',
      duration: '45 Minutes',
      roundName: 'Round 1: Technical Discussion',
      interviewer: 'Vageesha Sharma (Founder & Hiring Lead)',
      meetLink: 'https://meet.google.com/qoy-livx-rku',
      format: 'Google Meet Video Call',
      preparationNotes: 'Review relevant domain technologies.'
    } : null,
    emailSubject: isSelected ? `🎉 Interview Invitation: ${input.roleApplied} - Vageesha Sharma` : `Update regarding your application for ${input.roleApplied} - Vageesha Sharma`,
    emailHtmlBody: `<p>Dear ${input.candidateName},</p><p>Thank you for your application for ${input.roleApplied}.</p>`
  };
}

const finalCandidate = {
  id: 'cand-' + Date.now(),
  name: evaluationResult.candidateName || input.candidateName,
  email: input.candidateEmail || evaluationResult.candidateEmail,
  phone: evaluationResult.candidatePhone || 'Not specified',
  education: evaluationResult.education || 'Degree not specified',
  roleApplied: evaluationResult.roleApplied || input.roleApplied,
  experienceYears: evaluationResult.experienceYears || 0,
  skills: evaluationResult.skills || [],
  missingSkills: evaluationResult.missingSkills || [],
  scoreBreakdown: evaluationResult.scoreBreakdown || { technicalSkills: 20, experienceRelevance: 20, education: 15, communication: 15 },
  matchScore: evaluationResult.matchScore || 50,
  status: evaluationResult.status === 'SELECTED' ? 'SELECTED' : 'REJECTED',
  receivedAt: input.receivedTimestamp,
  evaluatedAt: new Date().toISOString(),
  summary: evaluationResult.summary,
  strengths: evaluationResult.strengths || [],
  weaknesses: evaluationResult.weaknesses || [],
  interviewSchedule: evaluationResult.status === 'SELECTED' ? evaluationResult.interviewSchedule : null,
  emailSubject: evaluationResult.emailSubject,
  emailHtmlBody: evaluationResult.emailHtmlBody,
  emailStatus: 'SENT',
  source: input.source
};

return [{
  json: finalCandidate
}];

// Step 5A: Dispatch Interview Schedule & Invitation Email from sharmavageesha2000@gmail.com
const cand = $json;

const emailDispatch = {
  from: 'Vageesha Sharma <sharmavageesha2000@gmail.com>',
  to: cand.email,
  subject: cand.emailSubject || `🎉 Interview Invitation: ${cand.roleApplied} - Vageesha Sharma's Team`,
  html: cand.emailHtmlBody,
  status: 'SENT_VIA_GMAIL_SMTP',
  dispatchedAt: new Date().toISOString()
};

return [{
  json: {
    ...cand,
    emailDispatch,
    emailStatus: 'SENT'
  }
}];

// Step 5B: Dispatch Detailed Rejection & Feedback Email from sharmavageesha2000@gmail.com
const cand = $json;

const emailDispatch = {
  from: 'Vageesha Sharma <sharmavageesha2000@gmail.com>',
  to: cand.email,
  subject: cand.emailSubject || `Update regarding your application for ${cand.roleApplied} - Vageesha Sharma`,
  html: cand.emailHtmlBody,
  status: 'SENT_VIA_GMAIL_SMTP',
  dispatchedAt: new Date().toISOString()
};

return [{
  json: {
    ...cand,
    emailDispatch,
    emailStatus: 'SENT'
  }
}];

// Step 6: Sync & Persist Evaluated Candidate to HR Database
const fs = require('fs');
const path = require('path');

const cand = $json;
const possiblePaths = [
  path.resolve('c:/Users/VAGEESHA/Desktop/my new n8n/data/candidates.json'),
  path.resolve('c:/Users/VAGEESHA/Desktop/my n8n new/data/candidates.json'),
  path.resolve('./data/candidates.json')
];

let targetPath = possiblePaths[0];
for (const p of possiblePaths) {
  const dir = path.dirname(p);
  if (fs.existsSync(dir)) {
    targetPath = p;
    break;
  }
}

try {
  fs.mkdirSync(path.dirname(targetPath), { recursive: true });
} catch (e) {}

let candidateList = [];
if (fs.existsSync(targetPath)) {
  try {
    candidateList = JSON.parse(fs.readFileSync(targetPath, 'utf8'));
    if (!Array.isArray(candidateList)) candidateList = [];
  } catch (e) {
    candidateList = [];
  }
}

// Update existing or prepend new candidate
const existingIdx = candidateList.findIndex(c => c.id === cand.id || (c.email === cand.email && c.roleApplied === cand.roleApplied));
if (existingIdx >= 0) {
  candidateList[existingIdx] = { ...candidateList[existingIdx], ...cand };
} else {
  candidateList.unshift(cand);
}

try {
  fs.writeFileSync(targetPath, JSON.stringify(candidateList, null, 2), 'utf8');
} catch (err) {}

return [{
  json: {
    success: true,
    candidate: cand,
    totalCandidatesInDb: candidateList.length,
    persistedAt: new Date().toISOString()
  }
}];
